import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const CLICKSIGN_API_KEY = Deno.env.get("CLICKSIGN_API_KEY");
const CLICKSIGN_BASE_URL = "https://app.clicksign.com/api/v3";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

// ─── Templates embutidos ───────────────────────────────────────────────────────
const TEMPLATES: Record<string, string> = {
  contrato_honorarios: "",
  procuracao: "",
  declaracao_hipossuficiencia: "",
  declaracao_golpe_falso_advogado: "",
};

const TEMPLATE_LABELS: Record<string, string> = {
  contrato_honorarios: "Contrato de Honorários",
  procuracao: "Procuração",
  declaracao_hipossuficiencia: "Declaração de Hipossuficiência",
  declaracao_golpe_falso_advogado: "Declaração Golpe Falso Advogado",
};

// ─── Headers padrão API v3 ────────────────────────────────────────────────────
const v3Headers = {
  "Authorization": CLICKSIGN_API_KEY!,
  "Content-Type": "application/vnd.api+json",
  "Accept": "application/vnd.api+json",
};

// ─── Retry helper ─────────────────────────────────────────────────────────────
async function apiFetch(url: string, options: RequestInit, retries = 3): Promise<Response> {
  for (let i = 0; i < retries; i++) {
    try {
      return await fetch(url, options);
    } catch (err: any) {
      if (i === retries - 1) throw err;
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
    }
  }
  throw new Error("Max retries exceeded");
}

// ─── Preenchimento de placeholders no DOCX ────────────────────────────────────
async function fillDocxTemplate(templateBase64: string, replacements: Record<string, string>): Promise<string> {
  const { ZipReader, ZipWriter, BlobReader, BlobWriter, TextReader, TextWriter } =
    await import("https://esm.sh/@zip.js/zip.js@2.7.32");

  const binaryStr = atob(templateBase64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);

  const zipReader = new ZipReader(new BlobReader(new Blob([bytes])));
  const entries = await zipReader.getEntries();
  const files = new Map<string, string | Uint8Array>();

  for (const entry of entries) {
    if (!entry.getData) continue;
    const isText = entry.filename.endsWith(".xml") || entry.filename.endsWith(".rels");
    if (isText) {
      files.set(entry.filename, await entry.getData(new TextWriter()));
    } else {
      const blob = await entry.getData(new BlobWriter());
      files.set(entry.filename, new Uint8Array(await blob.arrayBuffer()));
    }
  }
  await zipReader.close();

  let docXml = files.get("word/document.xml") as string;
  if (docXml) {
    for (const [placeholder, value] of Object.entries(replacements)) {
      const xmlSafe = value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      docXml = docXml.split(placeholder).join(xmlSafe);
    }
    files.set("word/document.xml", docXml);
  }

  const zipWriter = new ZipWriter(new BlobWriter("application/vnd.openxmlformats-officedocument.wordprocessingml.document"));
  for (const [filename, content] of files) {
    if (typeof content === "string") {
      await zipWriter.add(filename, new TextReader(content));
    } else {
      await zipWriter.add(filename, new BlobReader(new Blob([content])));
    }
  }
  const resultBlob = await zipWriter.close();
  const resultBytes = new Uint8Array(await resultBlob.arrayBuffer());
  let binary = "";
  for (let i = 0; i < resultBytes.length; i++) binary += String.fromCharCode(resultBytes[i]);
  return btoa(binary);
}

// ─── Handler principal ────────────────────────────────────────────────────────
serve(async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    if (!CLICKSIGN_API_KEY) throw new Error("CLICKSIGN_API_KEY não configurada");

    const { lead, signatario } = await req.json();
    if (!lead?.nome) throw new Error("lead.nome é obrigatório");
    if (!signatario?.email) throw new Error("signatario.email é obrigatório");
    if (!lead?.banco_reu) throw new Error("lead.banco_reu é obrigatório");

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

    // ── Data e qualificação ────────────────────────────────────────────────
    const meses = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
    const now = new Date();
    const dataExtenso = `${now.getDate()} de ${meses[now.getMonth()]} de ${now.getFullYear()}`;
    const qualificacao = [lead.nacionalidade || "brasileiro(a)", lead.estado_civil || "", lead.profissao || ""].filter(Boolean).join(", ");

    const replacements: Record<string, string> = {
      "(nome completo)": lead.nome,
      "(NOME COMPLETO)": lead.nome.toUpperCase(),
      "(qualificação completa)": qualificacao,
      "(xxxxxxx)": lead.rg || "não informado",
      "(xxxxxxxxx)": lead.cpf || "não informado",
      "(endereço completo)": lead.endereco || "não informado",
      "(xxxx)": lead.numero || "s/n",
      "(xxxxx)": lead.bairro || "não informado",
      "Cep: (xxxxxxx)": `Cep: ${lead.cep || "não informado"}`,
      "XX de XXXXXXXXX de 2026": dataExtenso,
      "xx de xxxxxxxxxxxx de 2026": dataExtenso,
      "XX de XXXXXXX de 2026": dataExtenso,
      "(XXXXXXXXXXXXXXX)": lead.banco_reu,
      "xxxxxxxxxxxxxxxxxxxx": lead.banco_reu.toLowerCase(),
      "(DDD) XXXXXX-XXXXXX": lead.telefone || "não informado",
    };

    const primeiroNome = lead.nome.split(" ")[0];

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 1 — Criar Envelope
    // ═══════════════════════════════════════════════════════════════════════
    console.log("[generate-kit] Criando envelope...");
    const envelopeRes = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes`, {
      method: "POST",
      headers: v3Headers,
      body: JSON.stringify({
        data: {
          type: "envelopes",
          attributes: {
            name: `Kit Bancário - ${lead.nome} - ${lead.banco_reu}`,
            locale: "pt-BR",
          }
        }
      }),
    });
    if (!envelopeRes.ok) throw new Error(`Criar envelope: ${await envelopeRes.text()}`);
    const envelopeData = await envelopeRes.json();
    const envelopeId = envelopeData.data?.id;
    if (!envelopeId) throw new Error("Envelope ID não retornado");
    console.log(`[generate-kit] Envelope criado: ${envelopeId}`);

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 2 — Adicionar os 4 documentos ao envelope
    // ═══════════════════════════════════════════════════════════════════════
    const documentIds: { id: string; nome: string }[] = [];

    for (const [templateKey, templateB64] of Object.entries(TEMPLATES)) {
      const label = TEMPLATE_LABELS[templateKey];
      console.log(`[generate-kit] Adicionando doc: ${label}`);

      const filledBase64 = await fillDocxTemplate(templateB64, replacements);
      const fileName = `${primeiroNome} - ${label}.docx`;

      const docRes = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/documents`, {
        method: "POST",
        headers: v3Headers,
        body: JSON.stringify({
          data: {
            type: "documents",
            attributes: {
              filename: fileName,
              content_base64: `data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,${filledBase64}`,
            }
          }
        }),
      });
      if (!docRes.ok) throw new Error(`Adicionar doc ${label}: ${await docRes.text()}`);
      const docData = await docRes.json();
      const docId = docData.data?.id;
      if (!docId) throw new Error(`Doc ID não retornado para ${label}`);
      console.log(`[generate-kit] Doc adicionado: ${docId}`);
      documentIds.push({ id: docId, nome: label });
    }

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 3 — Adicionar signatário ao envelope
    // ═══════════════════════════════════════════════════════════════════════
    console.log(`[generate-kit] Adicionando signatário: ${signatario.email}`);
    const signerRes = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/signers`, {
      method: "POST",
      headers: v3Headers,
      body: JSON.stringify({
        data: {
          type: "signers",
          attributes: {
            name: signatario.nome,
            email: signatario.email,
            phone_number: signatario.telefone || undefined,
          }
        }
      }),
    });
    if (!signerRes.ok) throw new Error(`Adicionar signatário: ${await signerRes.text()}`);
    const signerData = await signerRes.json();
    const signerId = signerData.data?.id;
    const signerUrl = signerData.data?.attributes?.url || null;
    if (!signerId) throw new Error("Signer ID não retornado");
    console.log(`[generate-kit] Signatário adicionado: ${signerId}, URL: ${signerUrl}`);

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 4 — Criar requisitos (assinar + autenticar) para cada documento
    // ═══════════════════════════════════════════════════════════════════════
    for (const doc of documentIds) {
      // Requisito de qualificação (assinar)
      const reqSign = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/requirements`, {
        method: "POST",
        headers: v3Headers,
        body: JSON.stringify({
          data: {
            type: "requirements",
            attributes: { action: "agree", role: "sign" },
            relationships: {
              document: { data: { type: "documents", id: doc.id } },
              signer: { data: { type: "signers", id: signerId } },
            }
          }
        }),
      });
      if (!reqSign.ok) console.warn(`Req sign ${doc.nome}: ${await reqSign.text()}`);

      // Requisito de autenticação (email/whatsapp/sms)
      const authType = signatario.auth_type || "email";
      const reqAuth = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/requirements`, {
        method: "POST",
        headers: v3Headers,
        body: JSON.stringify({
          data: {
            type: "requirements",
            attributes: {
              action: "provide_evidence",
              auth: authType,
            },
            relationships: {
              document: { data: { type: "documents", id: doc.id } },
              signer: { data: { type: "signers", id: signerId } },
            }
          }
        }),
      });
      if (!reqAuth.ok) console.warn(`Req auth ${doc.nome}: ${await reqAuth.text()}`);
    }
    console.log("[generate-kit] Requisitos criados para todos os docs");

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 5 — Ativar o envelope (status: running)
    // ═══════════════════════════════════════════════════════════════════════
    const activateRes = await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}`, {
      method: "PATCH",
      headers: v3Headers,
      body: JSON.stringify({
        data: {
          id: envelopeId,
          type: "envelopes",
          attributes: { status: "running" }
        }
      }),
    });
    if (!activateRes.ok) throw new Error(`Ativar envelope: ${await activateRes.text()}`);
    console.log("[generate-kit] Envelope ativado!");

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 6 — Disparar notificações (email automático do Clicksign)
    // ═══════════════════════════════════════════════════════════════════════
    await apiFetch(`${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/notifications`, {
      method: "POST",
      headers: v3Headers,
      body: JSON.stringify({ data: { type: "notifications", attributes: {} } }),
    });
    console.log("[generate-kit] Notificações disparadas");

    // ── Buscar URL de assinatura APÓS ativação ────────────────────────────
    // A URL pré-ativação (signerUrl da criação) pode ser inválida.
    // Sempre re-buscamos o signer após o envelope estar "running".
    let signLink: string | null = null;
    try {
      const signerGetRes = await apiFetch(
        `${CLICKSIGN_BASE_URL}/envelopes/${envelopeId}/signers/${signerId}`,
        { method: "GET", headers: v3Headers }
      );
      if (signerGetRes.ok) {
        const sg = await signerGetRes.json();
        signLink = sg.data?.attributes?.url || null;
      }
    } catch { /* ignora */ }
    if (!signLink) signLink = signerUrl; // fallback: URL de criação
    console.log(`[generate-kit] Link de assinatura: ${signLink}`);

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 7 — Salvar no banco
    // ═══════════════════════════════════════════════════════════════════════
    if (lead.id && signLink) {
      await supabase
        .from("leads_juridicos")
        .update({
          link_contrato: signLink,
          contract_key: envelopeId,
          contract_sent_at: new Date().toISOString(),
        })
        .eq("id", lead.id);

      // Salvar um registro por documento (para rastreamento)
      const reminders = documentIds.map(doc => ({
        document_key: doc.id,
        document_name: doc.nome,
        contract_link: signLink,
        lead_id: lead.id,
        signer_name: signatario.nome,
        signer_email: signatario.email,
        signer_phone: signatario.telefone,
        status: "pending",
      }));
      await supabase.from("contract_reminders").insert(reminders);

      await supabase.from("interacoes").insert({
        cliente_id: lead.id,
        tipo: "Documento",
        resumo: `Kit bancário enviado via envelope (${documentIds.length} documentos)`,
        detalhes: `Envelope: ${envelopeId}\nLink: ${signLink}\nBanco: ${lead.banco_reu}`,
      });
    }

    // ═══════════════════════════════════════════════════════════════════════
    // PASSO 8 — Enviar WhatsApp com o link único
    // ═══════════════════════════════════════════════════════════════════════
    if (signatario.telefone && signLink && lead.id) {
      try {
        const msg =
          `Olá ${primeiroNome}! 👋\n\n` +
          `Seus documentos estão prontos para assinatura digital.\n\n` +
          `📋 *${documentIds.length} documentos* aguardam sua assinatura:\n` +
          documentIds.map((d, i) => `${i + 1}. ${d.nome}`).join("\n") +
          `\n\n✍️ *Assine todos aqui (link único):*\n${signLink}\n\n` +
          `_Bentes Ramos Advocacia_\n📞 (92) 99160-4348`;

        await supabase.functions.invoke("zapi-send", {
          body: { to_phone: signatario.telefone, message: msg, lead_id: lead.id, type: "text" },
        });
        console.log(`[generate-kit] WhatsApp enviado para ${signatario.telefone}`);
      } catch (e) {
        console.warn("[generate-kit] WhatsApp falhou (não crítico):", e);
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        envelopeId,
        signLink,
        documentos: documentIds.map(d => ({ nome: d.nome, signLink })),
        total: documentIds.length,
      }),
      { status: 200, headers: { "Content-Type": "application/json", ...corsHeaders } }
    );

  } catch (err: any) {
    console.error("[generate-kit] Erro:", err);
    return new Response(
      JSON.stringify({ error: err.message }),
      { status: 500, headers: { "Content-Type": "application/json", ...corsHeaders } }
    );
  }
});
